<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('vitals.php');$page_title='Vital Signs';$page_subtitle=is_role('nurse')?'Input tanda vital oleh perawat. Dokter dan pasien melihat hasil secara read-only.':'Monitoring tanda vital sesuai kewenangan role.';$msg='';
function vital_status($t,$sys,$dia,$pulse,$rr,$spo2): string { if($t<35||$t>=39||$sys<90||$sys>=180||$dia<60||$dia>=120||$pulse<50||$pulse>=130||$rr<8||$rr>=30||$spo2<90)return 'critical'; if($t<36||$t>=38||$sys<100||$sys>=160||$dia<65||$dia>=100||$pulse<60||$pulse>=110||$rr<12||$rr>=24||$spo2<94)return 'warning'; return 'normal'; }
if($_SERVER['REQUEST_METHOD']==='POST'&&is_role('nurse')){check_csrf();$keys=['patient_id','temperature','systolic','diastolic','pulse','respiratory_rate','spo2'];$v=[];foreach($keys as $k)$v[$k]=$_POST[$k]??'';$valid=is_numeric($v['patient_id'])&&is_numeric($v['temperature'])&&is_numeric($v['systolic'])&&is_numeric($v['diastolic'])&&is_numeric($v['pulse'])&&is_numeric($v['respiratory_rate'])&&is_numeric($v['spo2'])&&$v['temperature']>=25&&$v['temperature']<=45&&$v['systolic']>=50&&$v['systolic']<=300&&$v['diastolic']>=20&&$v['diastolic']<=200&&$v['pulse']>=20&&$v['pulse']<=250&&$v['respiratory_rate']>=3&&$v['respiratory_rate']<=80&&$v['spo2']>=50&&$v['spo2']<=100;if(!$valid)$msg='Data vital sign tidak valid.';else{$st=vital_status((float)$v['temperature'],(int)$v['systolic'],(int)$v['diastolic'],(int)$v['pulse'],(int)$v['respiratory_rate'],(float)$v['spo2']);$s=$pdo->prepare('INSERT INTO vital_signs(patient_id,recorded_by,temperature,systolic,diastolic,pulse,respiratory_rate,spo2,pain_score,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$v['patient_id'],current_user_id(),$v['temperature'],$v['systolic'],$v['diastolic'],$v['pulse'],$v['respiratory_rate'],$v['spo2'],(int)($_POST['pain_score']??0),$st,trim($_POST['notes']??'')]);audit($pdo,'CREATE','VITAL_SIGN',(int)$pdo->lastInsertId(),'Tanda vital dicatat oleh perawat.');$msg='Vital sign berhasil disimpan.';}}
$patients=$pdo->query('SELECT id,mrn,name FROM patients ORDER BY name')->fetchAll();$where='';$params=[];if(is_role('patient')){$where='WHERE v.patient_id=?';$params=[current_patient_id($pdo)??0];}elseif(is_role('doctor')){$where='WHERE EXISTS(SELECT 1 FROM encounters e WHERE e.patient_id=v.patient_id AND e.doctor_id=?)';$params=[doctor_id($pdo)];}$sql="SELECT v.*,p.mrn,p.name,u.name recorder FROM vital_signs v JOIN patients p ON p.id=v.patient_id JOIN users u ON u.id=v.recorded_by $where ORDER BY v.recorded_at DESC LIMIT 100";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();include __DIR__.'/includes/header.php';?>
<?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?>
<?php if(is_role('nurse')):?><div class="card"><div class="card-header"><div><h3 class="section-title">Input Vital Sign</h3><p class="section-subtitle">Pencatat klinis: perawat. Setelah tersimpan, data bersifat historis/read-only.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div><label>Pasien</label><select name="patient_id" required><option value="">Pilih pasien</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=h($p['mrn'].' — '.$p['name'])?></option><?php endforeach;?></select></div><div><label>Temperature °C</label><input type="number" step=".1" name="temperature" required></div><div><label>BP Systolic</label><input type="number" name="systolic" required></div><div><label>BP Diastolic</label><input type="number" name="diastolic" required></div><div><label>Pulse /min</label><input type="number" name="pulse" required></div><div><label>Respiratory /min</label><input type="number" name="respiratory_rate" required></div><div><label>SpO₂ %</label><input type="number" step=".1" name="spo2" required></div><div><label>Pain 0–10</label><input type="number" min="0" max="10" name="pain_score" value="0"></div><div style="grid-column:1/-1"><label>Catatan</label><input name="notes" placeholder="Posisi pasien / alat ukur / observasi tambahan"></div><div><button class="btn primary">Simpan Vital Sign</button></div></form></div><div style="height:18px"></div><?php endif;?>
<div class="card"><div class="card-header"><div><h3 class="section-title">Monitoring Chart</h3><p class="section-subtitle"><?=count($rows)?> pemeriksaan dalam cakupan akses.</p></div></div><div class="table-wrap"><table><tr><th>Pasien</th><th>Waktu</th><th>Temp</th><th>BP</th><th>Pulse</th><th>RR</th><th>SpO₂</th><th>Pain</th><th>Status</th><th>Pencatat</th></tr><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b><br><span class="mini"><?=h($r['mrn'])?></span></td><td><?=h(date('d/m/Y H:i',strtotime($r['recorded_at'])))?></td><td><?=h($r['temperature'])?>°</td><td><?=h($r['systolic'])?>/<?=h($r['diastolic'])?></td><td><?=h($r['pulse'])?></td><td><?=h($r['respiratory_rate'])?></td><td><?=h($r['spo2'])?>%</td><td><?=h((string)$r['pain_score'])?></td><td><span class="badge <?=$r['status']==='critical'?'danger':($r['status']==='warning'?'warn':'ok')?>"><?=h(strtoupper($r['status']))?></span></td><td><?=h($r['recorder'])?></td></tr><?php endforeach;?></table></div></div><?php include __DIR__.'/includes/footer.php';?>